1	// contractlab —— 可热更新的本地接口场景服务
2	//
3	// 运行环境：Node.js 24（内置 TypeScript 类型擦除，可直接 `node app.ts`），
4	// 无任何外部运行依赖。
5	//
6	// 行为约定（详见 README.md）：
7	// - 业务接口由“方法 + 绝对路径”唯一标识，查询串不参与匹配，不支持路径模板；
8	// - 请求被完整接收后，才按当前配置匹配接口并同步“预留”响应序列的下一项，
9	//   序列耗尽后持续返回末项；预留之后客户端断开，仍计为一次消费；
10	// - POST /__contractlab/reload 重新读取同一配置文件：新配置全部有效时才
11	//   原子替换全部接口、重置全部序列并递增版本号；失败时现状不变；
12	// - 在途请求持有预留时的旧响应快照（状态码/响应头/正文/延迟/版本），
13	//   完成时不会推进新序列；
14	// - POST 接口可附加可选的 requestBody 正文结构规则：请求完整接收后先校验
15	//   媒体类型与 JSON 结构，不符时返回 400 差异报告，不发送场景响应、不消费序列；
16	//   校验通过才按“完整接收”顺序预留响应项。
17	
18	import http from 'node:http';
19	import { readFile } from 'node:fs/promises';
20	import path from 'node:path';
21	
22	const APP_NAME = 'contractlab';
23	
24	// 管理入口（保留前缀，业务接口不得使用）
25	const ADMIN_PREFIX = '/__contractlab/';
26	const HEALTH_PATH = '/__contractlab/health';
27	const RELOAD_PATH = '/__contractlab/reload';
28	
29	// 每个业务响应都携带当前配置版本
30	const VERSION_HEADER = 'X-Contractlab-Version';
31	
32	// 请求体上限（本机工具的防误操作保护，超出直接 413，不触碰任何序列）
33	const MAX_BODY_BYTES = 100 * 1024 * 1024;
34	
35	// 由服务器管理、业务配置不得覆盖的“传输头”（大小写不敏感）
36	const BLOCKED_HEADERS = new Set([
37	  'connection',
38	  'keep-alive',
39	  'content-length',
40	  'transfer-encoding',
41	]);
42	
43	// RFC 7230 token：合法的 HTTP 头名称字符
44	const HEADER_NAME_RE = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/;
45	
46	type HttpMethod = 'GET' | 'POST';
47	
48	// ---------------------------------------------------------------------------
49	// 请求正文结构规则（endpoints[].requestBody，仅 POST）
50	// ---------------------------------------------------------------------------
51	//
52	// 规则格式（JSON 对象，未知字段一律拒绝）：
53	//   { "type": "object", "fields": { "<名>": <字段规则>, ... }, "additionalProperties": false }
54	//   { "type": "array", "items": <规则> }
55	//   { "type": "string" | "number" | "integer" | "boolean" | "null" }
56	// 字段规则 = 任意规则 + 可选 "required": true（缺省为可缺省）；
57	// object 的 fields / additionalProperties 可省略（默认无字段声明、拒绝未声明字段）；
58	// array 必须声明 items。
59	
60	type ScalarKind = 'string' | 'number' | 'integer' | 'boolean' | 'null';
61	
62	type BodyRule =
63	  | {
64	      readonly kind: 'object';
65	      readonly fields: ReadonlyMap<string, FieldRule>;
66	      readonly additionalProperties: boolean;
67	    }
68	  | { readonly kind: 'array'; readonly items: BodyRule }
69	  | { readonly kind: ScalarKind };
70	
71	interface FieldRule {
72	  readonly rule: BodyRule;
73	  readonly required: boolean;
74	}
75	
76	interface ResponseSpec {
77	  readonly status: number;
78	  readonly headers: { readonly [name: string]: string };
79	  readonly body: string;
80	  readonly delay: number;
81	}
82	
83	interface EndpointSpec {
84	  readonly method: HttpMethod;
85	  readonly path: string;
86	  readonly responses: readonly ResponseSpec[];
87	  readonly bodyRule: BodyRule | undefined;
88	}
89	
90	interface LiveEndpoint {
91	  readonly key: string;
92	  readonly responses: readonly ResponseSpec[];
93	  readonly bodyRule: BodyRule | undefined;
94	  // 下一个待预留位置；到达末项后停在末项（持续复用）
95	  cursor: number;
96	}
97	
98	interface LiveState {
99	  readonly version: number;
100	  readonly endpoints: ReadonlyMap<string, LiveEndpoint>;
101	}
102	
103	interface ReloadResult {
104	  ok: boolean;
105	  version: number;
106	  error?: string;
107	}
108	
109	class ConfigError extends Error {
110	  constructor(message: string) {
111	    super(message);
112	    this.name = 'ConfigError';
113	  }
114	}
115	
116	// ---------------------------------------------------------------------------
117	// 配置校验
118	// ---------------------------------------------------------------------------
119	
120	function isPlainObject(value: unknown): value is Record<string, unknown> {
121	  return typeof value === 'object' && value !== null && !Array.isArray(value);
122	}
123	
124	function validatePath(p: string, where: string): void {
125	  if (p.length === 0 || p[0] !== '/') {
126	    throw new ConfigError(`${where}.path 必须是以 "/" 开头的绝对路径，收到 "${p}"`);
127	  }
128	  if (p.length > 4096) {
129	    throw new ConfigError(`${where}.path 过长（最多 4096 字符）`);
130	  }
131	  for (const ch of p) {
132	    const code = ch.charCodeAt(0);
133	    if (ch === '?' || ch === '#' || ch === '{' || ch === '}') {
134	      throw new ConfigError(
135	        `${where}.path "${p}" 含有非法字符 "${ch}"：查询串不参与匹配，且不支持路径模板`,
136	      );
137	    }
138	    if (code <= 0x1f || code === 0x7f || code === 0x20) {
139	      throw new ConfigError(`${where}.path "${p}" 不得包含空白或控制字符`);
140	    }
141	  }
142	}
143	
144	function validateResponse(raw: unknown, where: string): ResponseSpec {
145	  if (!isPlainObject(raw)) {
146	    throw new ConfigError(`${where} 必须是对象`);
147	  }
148	  for (const key of Object.keys(raw)) {
149	    if (key !== 'status' && key !== 'headers' && key !== 'body' && key !== 'delay') {
150	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
151	    }
152	  }
153	
154	  const { status, headers, body, delay } = raw;
155	
156	  if (!Number.isInteger(status) || status < 200 || status > 599) {
157	    throw new ConfigError(`${where}.status 必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`);
158	  }
159	
160	  if (!isPlainObject(headers)) {
161	    throw new ConfigError(`${where}.headers 必须是字符串键值对象`);
162	  }
163	  const cleanHeaders: { [name: string]: string } = {};
164	  const seenNames = new Set<string>();
165	  for (const [name, value] of Object.entries(headers)) {
166	    const whereHeader = `${where}.headers["${name}"]`;
167	    if (!HEADER_NAME_RE.test(name)) {
168	      throw new ConfigError(`${whereHeader} 不是合法的 HTTP 响应头名称`);
169	    }
170	    const lower = name.toLowerCase();
171	    if (BLOCKED_HEADERS.has(lower)) {
172	      throw new ConfigError(`${whereHeader} 属于服务器管理的传输头，不允许在配置中设置`);
173	    }
174	    if (seenNames.has(lower)) {
175	      throw new ConfigError(`${whereHeader} 与同序列内另一个响应头仅大小写不同，视为重复`);
176	    }
177	    if (typeof value !== 'string') {
178	      throw new ConfigError(`${whereHeader} 的值必须是字符串`);
179	    }
180	    for (let i = 0; i < value.length; i += 1) {
181	      const code = value.charCodeAt(i);
182	      // 允许水平制表符(0x09)；拒绝换行及其余控制字符；
183	      // Node 的 HTTP 头值只支持 Latin-1（0x80-0xFF），更高码位发送时会抛错
184	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
185	        throw new ConfigError(
186	          `${whereHeader} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
187	        );
188	      }
189	    }
190	    seenNames.add(lower);
191	    cleanHeaders[name] = value;
192	  }
193	
194	  if (typeof body !== 'string') {
195	    throw new ConfigError(`${where}.body 必须是文本字符串`);
196	  }
197	  if ((status === 204 || status === 304) && body !== '') {
198	    throw new ConfigError(`${where}.body 状态码为 ${status} 时正文必须为空字符串`);
199	  }
200	
201	  if (!Number.isInteger(delay) || delay < 0 || delay > 60000) {
202	    throw new ConfigError(`${where}.delay 必须是 0 至 60000 之间的整数毫秒数，收到 ${JSON.stringify(delay)}`);
203	  }
204	
205	  return { status, headers: cleanHeaders, body, delay };
206	}
207	
208	const SCALAR_KINDS: ReadonlySet<string> = new Set([
209	  'string',
210	  'number',
211	  'integer',
212	  'boolean',
213	  'null',
214	]);
215	
216	function validateBodyRule(raw: unknown, where: string): BodyRule {
217	  if (!isPlainObject(raw)) {
218	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
219	  }
220	
221	  const type = raw.type;
222	  const allowed = new Set(['type']);
223	  if (type === 'object') {
224	    allowed.add('fields');
225	    allowed.add('additionalProperties');
226	  } else if (type === 'array') {
227	    allowed.add('items');
228	  } else if (!SCALAR_KINDS.has(type as string)) {
229	    throw new ConfigError(
230	      `${where}.type 必须是 "object" | "array" | "string" | "number" | "integer" | "boolean" | "null"，收到 ${JSON.stringify(type)}`,
231	    );
232	  }
233	  for (const key of Object.keys(raw)) {
234	    if (!allowed.has(key)) {
235	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
236	    }
237	  }
238	
239	  if (type === 'object') {
240	    const fieldsRaw = raw.fields;
241	    const fields = new Map<string, FieldRule>();
242	    if (fieldsRaw !== undefined) {
243	      if (!isPlainObject(fieldsRaw)) {
244	        throw new ConfigError(`${where}.fields 必须是对象（字段名 → 字段规则）`);
245	      }
246	      for (const [name, fieldRaw] of Object.entries(fieldsRaw)) {
247	        fields.set(name, validateFieldRule(fieldRaw, `${where}.fields[${JSON.stringify(name)}]`));
248	      }
249	    }
250	    const additional = raw.additionalProperties;
251	    if (additional !== undefined && typeof additional !== 'boolean') {
252	      throw new ConfigError(`${where}.additionalProperties 必须是布尔值`);
253	    }
254	    // 未声明字段默认拒绝
255	    return { kind: 'object', fields, additionalProperties: additional === true };
256	  }
257	
258	  if (type === 'array') {
259	    if (raw.items === undefined) {
260	      throw new ConfigError(`${where}.items 数组规则必须声明元素规则`);
261	    }
262	    return { kind: 'array', items: validateBodyRule(raw.items, `${where}.items`) };
263	  }
264	
265	  return { kind: type as ScalarKind };
266	}
267	
268	// 字段规则 = 任意规则 + 可选 "required"（仅允许出现在 object 的 fields 条目中）
269	function validateFieldRule(raw: unknown, where: string): FieldRule {
270	  if (!isPlainObject(raw)) {
271	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
272	  }
273	  let required = false;
274	  const rest: Record<string, unknown> = {};
275	  for (const [key, value] of Object.entries(raw)) {
276	    if (key === 'required') {
277	      if (typeof value !== 'boolean') {
278	        throw new ConfigError(`${where}.required 必须是布尔值`);
279	      }
280	      required = value;
281	    } else {
282	      rest[key] = value;
283	    }
284	  }
285	  return { rule: validateBodyRule(rest, where), required };
286	}
287	
288	function validateEndpoint(
289	  raw: unknown,
290	  index: number,
291	  seen: Set<string>,
292	): EndpointSpec {
293	  const where = `endpoints[${index}]`;
294	  if (!isPlainObject(raw)) {
295	    throw new ConfigError(`${where} 必须是对象`);
296	  }
297	  for (const key of Object.keys(raw)) {
298	    if (key !== 'method' && key !== 'path' && key !== 'responses' && key !== 'requestBody') {
299	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
300	    }
301	  }
302	
303	  const { method, path: routePath, responses, requestBody } = raw;
304	
305	  if (method !== 'GET' && method !== 'POST') {
306	    throw new ConfigError(`${where}.method 必须是 "GET" 或 "POST"，收到 ${JSON.stringify(method)}`);
307	  }
308	
309	  if (typeof routePath !== 'string') {
310	    throw new ConfigError(`${where}.path 必须是字符串`);
311	  }
312	  validatePath(routePath, where);
313	  if (routePath === '/__contractlab' || routePath.startsWith(ADMIN_PREFIX)) {
314	    throw new ConfigError(
315	      `${where}.path "${routePath}" 与管理入口冲突：前缀 "${ADMIN_PREFIX}" 为管理接口保留`,
316	    );
317	  }
318	
319	  const key = `${method} ${routePath}`;
320	  if (seen.has(key)) {
321	    throw new ConfigError(`${where} 与其他接口重复（方法 + 路径必须唯一）：${key}`);
322	  }
323	  seen.add(key);
324	
325	  if (!Array.isArray(responses) || responses.length === 0) {
326	    throw new ConfigError(`${where}.responses 必须是非空数组`);
327	  }
328	  const cleanResponses = responses.map((item, j) =>
329	    validateResponse(item, `${where}.responses[${j}]`),
330	  );
331	
332	  let bodyRule: BodyRule | undefined;
333	  if (requestBody !== undefined) {
334	    if (method !== 'POST') {
335	      throw new ConfigError(`${where}.requestBody 仅允许在 POST 接口上声明（GET 接口不允许携带此规则）`);
336	    }
337	    bodyRule = validateBodyRule(requestBody, `${where}.requestBody`);
338	  }
339	
340	  return { method, path: routePath, responses: cleanResponses, bodyRule };
341	}
342	
343	function validateConfig(raw: unknown): EndpointSpec[] {
344	  if (!isPlainObject(raw)) {
345	    throw new ConfigError('配置顶层必须是 JSON 对象');
346	  }
347	  for (const key of Object.keys(raw)) {
348	    if (key !== 'endpoints') {
349	      throw new ConfigError(`未知顶层字段 "${key}"，仅允许 "endpoints"`);
350	    }
351	  }
352	  const list = raw.endpoints;
353	  if (!Array.isArray(list) || list.length === 0) {
354	    throw new ConfigError('endpoints 必须是至少包含一个接口的数组');
355	  }
356	  const seen = new Set<string>();
357	  return list.map((ep, i) => validateEndpoint(ep, i, seen));
358	}
359	
360	// ---------------------------------------------------------------------------
361	// 运行时状态：配置快照 + 每接口独立序列
362	// ---------------------------------------------------------------------------
363	
364	function buildState(version: number, specs: readonly EndpointSpec[]): LiveState {
365	  const endpoints = new Map<string, LiveEndpoint>();
366	  for (const spec of specs) {
367	    endpoints.set(`${spec.method} ${spec.path}`, {
368	      key: `${spec.method} ${spec.path}`,
369	      responses: spec.responses,
370	      bodyRule: spec.bodyRule,
371	      cursor: 0,
372	    });
373	  }
374	  return { version, endpoints };
375	}
376	
377	// 同步预留下一项；同一事件循环内按“完整接收”事件的先后串行调用，天然保序。
378	// 末项之后持续返回末项，不跳项、不复用未到位置的项。
379	function reserveNext(endpoint: LiveEndpoint): ResponseSpec {
380	  const last = endpoint.responses.length - 1;
381	  const position = endpoint.cursor < last ? endpoint.cursor : last;
382	  if (endpoint.cursor < last) {
383	    endpoint.cursor += 1;
384	  }
385	  return endpoint.responses[position];
386	}
387	
388	// ---------------------------------------------------------------------------
389	// 请求正文校验：媒体类型 → UTF-8 JSON 解析 → 结构比对
390	// ---------------------------------------------------------------------------
391	
392	interface StructureProblem {
393	  readonly pointer: string;
394	  readonly expected: string;
395	  readonly actual: string;
396	}
397	
398	interface BodyReport {
399	  readonly error: 'invalid_request_body';
400	  readonly stage: 'parse' | 'structure';
401	  readonly message: string;
402	  readonly problems: readonly StructureProblem[];
403	}
404	
405	function parseFailure(message: string): BodyReport {
406	  return { error: 'invalid_request_body', stage: 'parse', message, problems: [] };
407	}
408	
409	function jsonTypeOf(value: unknown): string {
410	  if (value === null) {
411	    return 'null';
412	  }
413	  if (Array.isArray(value)) {
414	    return 'array';
415	  }
416	  return typeof value;
417	}
418	
419	// RFC 6901 JSON Pointer 段转义：~ -> ~0，/ -> ~1
420	function escapePointerSegment(segment: string): string {
421	  return segment.replace(/~/g, '~0').replace(/\//g, '~1');
422	}
423	
424	// 结构比对：父节点类型不符时只报告该节点，不再深入制造子节点错误；
425	// 字段缺失（hasOwnProperty 为假）与合法的 JSON null 分开判断。
426	function checkRule(
427	  rule: BodyRule,
428	  value: unknown,
429	  pointer: string,
430	  problems: StructureProblem[],
431	): void {
432	  switch (rule.kind) {
433	    case 'string':
434	    case 'boolean':
435	      if (typeof value !== rule.kind) {
436	        problems.push({ pointer, expected: rule.kind, actual: jsonTypeOf(value) });
437	      }
438	      return;
439	    case 'null':
440	      if (value !== null) {
441	        problems.push({ pointer, expected: 'null', actual: jsonTypeOf(value) });
442	      }
443	      return;
444	    case 'number':
445	      if (typeof value !== 'number' || !Number.isFinite(value)) {
446	        problems.push({ pointer, expected: 'number', actual: jsonTypeOf(value) });
447	      }
448	      return;
449	    case 'integer':
450	      if (!Number.isInteger(value)) {
451	        problems.push({ pointer, expected: 'integer', actual: jsonTypeOf(value) });
452	      }
453	      return;
454	    case 'array': {
455	      if (!Array.isArray(value)) {
456	        problems.push({ pointer, expected: 'array', actual: jsonTypeOf(value) });
457	        return;
458	      }
459	      for (let i = 0; i < value.length; i += 1) {
460	        checkRule(rule.items, value[i], `${pointer}/${i}`, problems);
461	      }
462	      return;
463	    }
464	    case 'object': {
465	      if (!isPlainObject(value)) {
466	        problems.push({ pointer, expected: 'object', actual: jsonTypeOf(value) });
467	        return;
468	      }
469	      for (const [name, field] of rule.fields) {
470	        const childPointer = `${pointer}/${escapePointerSegment(name)}`;
471	        if (!Object.prototype.hasOwnProperty.call(value, name)) {
472	          if (field.required) {
473	            problems.push({
474	              pointer: childPointer,
475	              expected: `${field.rule.kind}（必填字段）`,
476	              actual: 'missing',
477	            });
478	          }
479	        } else {
480	          checkRule(field.rule, value[name], childPointer, problems);
481	        }
482	      }
483	      if (!rule.additionalProperties) {
484	        for (const key of Object.keys(value)) {
485	          if (!rule.fields.has(key)) {
486	            problems.push({
487	              pointer: `${pointer}/${escapePointerSegment(key)}`,
488	              expected: '未声明的字段（不允许）',
489	              actual: jsonTypeOf(value[key]),
490	            });
491	          }
492	        }
493	      }
494	      return;
495	    }
496	  }
497	}
498	
499	// 返回 null 表示校验通过；否则为可直接序列化的 400 差异报告
500	function validateRequestBody(
501	  req: http.IncomingMessage,
502	  body: Buffer,
503	  rule: BodyRule,
504	): BodyReport | null {
505	  const contentType = req.headers['content-type'];
506	  const mediaType =
507	    typeof contentType === 'string' ? contentType.split(';', 1)[0].trim().toLowerCase() : '';
508	  if (mediaType !== 'application/json') {
509	    return parseFailure(
510	      typeof contentType === 'string'
511	        ? `媒体类型不符：期望 application/json（可带参数、忽略大小写），收到 "${contentType}"`
512	        : '缺少 Content-Type 头：期望 application/json（可带参数、忽略大小写）',
513	    );
514	  }
515	
516	  if (body.length === 0) {
517	    return parseFailure('请求正文为空，无法解析为 JSON');
518	  }
519	
520	  let text: string;
521	  try {
522	    text = new TextDecoder('utf-8', { fatal: true }).decode(body);
523	  } catch {
524	    return parseFailure('请求正文不是合法的 UTF-8 编码');
525	  }
526	
527	  let parsed: unknown;
528	  try {
529	    parsed = JSON.parse(text);
530	  } catch (e) {
531	    return parseFailure(`请求正文不是合法 JSON：${describeError(e)}`);
532	  }
533	
534	  const problems: StructureProblem[] = [];
535	  checkRule(rule, parsed, '', problems);
536	  if (problems.length > 0) {
537	    return {
538	      error: 'invalid_request_body',
539	      stage: 'structure',
540	      message: `请求正文与接口约定存在 ${problems.length} 处差异`,
541	      problems,
542	    };
543	  }
544	  return null;
545	}
546	
547	// ---------------------------------------------------------------------------
548	// 文件读取与（重新）加载：读、解析、校验全部通过后才一次性替换
549	// ---------------------------------------------------------------------------
550	
551	function describeError(e: unknown): string {
552	  return e instanceof Error ? e.message : String(e);
553	}
554	
555	async function loadStateFromFile(configPath: string, version: number): Promise<LiveState> {
556	  let text: string;
557	  try {
558	    text = await readFile(configPath, 'utf8');
559	  } catch (e) {
560	    throw new Error(`读取配置文件 ${configPath} 失败：${describeError(e)}`);
561	  }
562	
563	  let raw: unknown;
564	  try {
565	    raw = JSON.parse(text);
566	  } catch (e) {
567	    throw new Error(`配置文件 ${configPath} 不是合法 JSON：${describeError(e)}`);
568	  }
569	
570	  try {
571	    const specs = validateConfig(raw);
572	    return buildState(version, specs);
573	  } catch (e) {
574	    throw new Error(`配置文件 ${configPath} 校验失败：${describeError(e)}`);
575	  }
576	}
577	
578	// ---------------------------------------------------------------------------
579	// HTTP 服务
580	// ---------------------------------------------------------------------------
581	
582	// 模块级运行时句柄（启动后赋值）
583	let activeState: LiveState;
584	let server: http.Server;
585	let configFile = '';
586	let shuttingDown = false;
587	
588	// 尚未发出的延迟响应定时器，关闭时统一取消
589	const pendingTimers = new Set<ReturnType<typeof setTimeout>>();
590	
591	// 重载按“触发顺序”串行处理：后一个 reload 必定在前一个落定后才读文件
592	let reloadChain: Promise<unknown> = Promise.resolve();
593	
594	function triggerReload(): Promise<ReloadResult> {
595	  const job = reloadChain.then(async (): Promise<ReloadResult> => {
596	    try {
597	      // 校验通过前只构造局部变量，任何失败都不会触碰 activeState
598	      const next = await loadStateFromFile(configFile, activeState.version + 1);
599	      activeState = next; // 单次同步赋值：请求不可能看到混合配置
600	      return { ok: true, version: activeState.version };
601	    } catch (e) {
602	      // 不修改配置/版本，不重置序列；旧场景的正常消费继续
603	      return { ok: false, version: activeState.version, error: describeError(e) };
604	    }
605	  });
606	  // 失败也不能打断后续 reload 的排队
607	  reloadChain = job.then(
608	    () => undefined,
609	    () => undefined,
610	  );
611	  return job;
612	}
613	
614	function writeResponse(
615	  res: http.ServerResponse,
616	  status: number,
617	  headers: { readonly [name: string]: string },
618	  body: string,
619	): void {
620	  try {
621	    res.writeHead(status, headers);
622	    res.end(body === '' ? undefined : body);
623	  } catch {
624	    // 预留之后客户端可能已断开：响应仍计为已消费，发送失败仅静默忽略
625	  }
626	}
627	
628	function versionHeaders(
629	  version: number,
630	  extra?: { readonly [name: string]: string },
631	): { [name: string]: string } {
632	  const headers: { [name: string]: string } = {
633	    [VERSION_HEADER]: String(version),
634	  };
635	  if (extra) {
636	    for (const [name, value] of Object.entries(extra)) {
637	      headers[name] = value;
638	    }
639	  }
640	  return headers;
641	}
642	
643	function sendJson(res: http.ServerResponse, status: number, value: unknown, version: number): void {
644	  writeResponse(
645	    res,
646	    status,
647	    versionHeaders(version, { 'Content-Type': 'application/json; charset=utf-8' }),
648	    `${JSON.stringify(value)}\n`,
649	  );
650	}
651	
652	function sendNotFound(res: http.ServerResponse): void {
653	  writeResponse(
654	    res,
655	    404,
656	    versionHeaders(activeState.version, {
657	      'Content-Type': 'text/plain; charset=utf-8',
658	    }),
659	    'not found\n',
660	  );
661	}
662	
663	function sendBusinessResponse(
664	  res: http.ServerResponse,
665	  item: ResponseSpec,
666	  version: number,
667	): void {
668	  const headers = versionHeaders(version);
669	  let contentTypeSet = false;
670	  for (const [name, value] of Object.entries(item.headers)) {
671	    const lower = name.toLowerCase();
672	    // 版本头由服务器填写且必须唯一准确：配置中的同名头（含大小写变体）可加载，发送时忽略其值
673	    if (lower === VERSION_HEADER.toLowerCase()) {
674	      continue;
675	    }
676	    if (lower === 'content-type') {
677	      contentTypeSet = true;
678	    }
679	    headers[name] = value;
680	  }
681	  // 文本正文的默认内容类型；配置显式给出时不覆盖
682	  if (!contentTypeSet && item.body !== '') {
683	    headers['Content-Type'] = 'text/plain; charset=utf-8';
684	  }
685	  writeResponse(res, item.status, headers, item.body);
686	}
687	
688	// 延迟结束才发送；即便客户端提前断开也继续计时（消费在预留时已经成立）
689	function scheduleBusinessResponse(
690	  res: http.ServerResponse,
691	  item: ResponseSpec,
692	  version: number,
693	): void {
694	  const timer = setTimeout(() => {
695	    pendingTimers.delete(timer);
696	    sendBusinessResponse(res, item, version);
697	  }, item.delay);
698	  pendingTimers.add(timer);
699	}
700	
701	type BodyOutcome = 'received' | 'aborted' | 'too-large';
702	
703	interface ReceivedBody {
704	  readonly outcome: BodyOutcome;
705	  // 仅在 outcome 为 'received' 时有意义（完整请求体）
706	  readonly body: Buffer;
707	}
708	
709	// 完整接收请求体；未完整接收即断开返回 'aborted'（调用方不得推进序列）
710	function receiveBody(req: http.IncomingMessage, res: http.ServerResponse): Promise<ReceivedBody> {
711	  return new Promise((resolve) => {
712	    let settled = false;
713	    let size = 0;
714	    const chunks: Buffer[] = [];
715	    const finish = (outcome: BodyOutcome): void => {
716	      if (!settled) {
717	        settled = true;
718	        resolve({ outcome, body: outcome === 'received' ? Buffer.concat(chunks) : Buffer.alloc(0) });
719	      }
720	    };
721	    req.on('data', (chunk: Buffer) => {
722	      size += chunk.byteLength;
723	      if (size > MAX_BODY_BYTES) {
724	        finish('too-large');
725	        writeResponse(
726	          res,
727	          413,
728	          versionHeaders(activeState.version, {
729	            'Content-Type': 'text/plain; charset=utf-8',
730	          }),
731	          'payload too large\n',
732	        );
733	        // 等 413 刷出后再断开，避免客户端收不到响应
734	        res.once('finish', () => req.socket.destroy());
735	        return;
736	      }
737	      chunks.push(chunk);
738	    });
739	    req.on('end', () => finish('received'));
740	    req.on('error', () => finish('aborted'));
741	    req.on('aborted', () => finish('aborted'));
742	    res.on('close', () => finish('aborted'));
743	  });
744	}
745	
746	async function dispatch(
747	  req: http.IncomingMessage,
748	  res: http.ServerResponse,
749	): Promise<void> {
750	  res.on('error', () => {
751	    // 写已销毁套接字等错误无需让进程崩溃
752	  });
753	
754	  const { outcome, body } = await receiveBody(req, res);
755	  if (outcome !== 'received') {
756	    // aborted：未完整接收，不匹配、不预留、不推进任何序列
757	    // too-large：已回复 413
758	    return;
759	  }
760	
761	  const method = String(req.method);
762	  const pathname = String(req.url ?? '/').split('?')[0]; // 查询串不参与匹配
763	
764	  // 管理入口（不消费任何业务序列）
765	  if (pathname === HEALTH_PATH) {
766	    if (method === 'GET') {
767	      sendJson(res, 200, { status: 'ok', version: activeState.version }, activeState.version);
768	    } else {
769	      sendNotFound(res);
770	    }
771	    return;
772	  }
773	
774	  if (pathname === RELOAD_PATH) {
775	    if (method === 'POST') {
776	      const result = await triggerReload();
777	      sendJson(res, 200, result, result.version);
778	    } else {
779	      sendNotFound(res);
780	    }
781	    return;
782	  }
783	
784	  // 业务匹配：在本次同步执行内抓取状态快照，预留后与后续 reload 互不影响
785	  const state = activeState;
786	  const endpoint =
787	    method === 'GET' || method === 'POST'
788	      ? state.endpoints.get(`${method} ${pathname}`)
789	      : undefined;
790	
791	  if (!endpoint) {
792	    sendNotFound(res); // 未匹配请求：404，不消费
793	    return;
794	  }
795	
796	  // 正文结构规则（如有）：校验失败返回 400 差异报告，不发送场景响应、不消费序列。
797	  // 规则、序列与版本均取自上面同一快照 state。
798	  if (endpoint.bodyRule) {
799	    const report = validateRequestBody(req, body, endpoint.bodyRule);
800	    if (report) {
801	      sendJson(res, 400, report, state.version);
802	      return;
803	    }
804	  }
805	
806	  const item = reserveNext(endpoint); // 校验通过后立即预留
807	  scheduleBusinessResponse(res, item, state.version);
808	}
809	
810	// ---------------------------------------------------------------------------
811	// 启动、信号处理
812	// ---------------------------------------------------------------------------
813	
814	function shutdown(): void {
815	  if (shuttingDown) {
816	    return;
817	  }
818	  shuttingDown = true;
819	  // 取消所有尚未发出的延迟响应
820	  for (const timer of pendingTimers) {
821	    clearTimeout(timer);
822	  }
823	  pendingTimers.clear();
824	  // 关闭监听并断开空闲/在途连接，随后正常退出（退出码 0）
825	  try {
826	    server.closeAllConnections();
827	  } catch {
828	    // 旧版本兜底：忽略，下面的 close/超时仍会结束进程
829	  }
830	  server.close(() => process.exit(0));
831	  setTimeout(() => process.exit(0), 2000).unref();
832	}
833	
834	async function startServer(configArg: string, port: number): Promise<void> {
835	  configFile = path.resolve(configArg);
836	
837	  // 先读配置：配置无效时根本不会创建监听
838	  activeState = await loadStateFromFile(configFile, 1);
839	
840	  server = http.createServer((req, res) => {
841	    dispatch(req, res).catch(() => {
842	      try {
843	        req.socket.destroy();
844	      } catch {
845	        // 套接字可能已销毁
846	      }
847	    });
848	  });
849	
850	  await new Promise<void>((resolve, reject) => {
851	    server.once('error', reject);
852	    // 仅监听本机回环地址
853	    server.listen(port, '127.0.0.1', resolve);
854	  });
855	
856	  const address = server.address();
857	  const actualPort = typeof address === 'object' && address ? address.port : port;
858	  process.stdout.write(
859	    `${APP_NAME}: listening on http://127.0.0.1:${actualPort}\n` +
860	      `${APP_NAME}: config ${configFile} (version 1, ${activeState.endpoints.size} endpoints)\n`,
861	  );
862	
863	  const onSignal = (): void => shutdown();
864	  process.on('SIGINT', onSignal);
865	  process.on('SIGTERM', onSignal);
866	}
867	
868	// ---------------------------------------------------------------------------
869	// 命令行
870	// ---------------------------------------------------------------------------
871	
872	function helpText(): string {
873	  return [
874	    APP_NAME,
875	    '',
876	    '可热更新的本地接口场景服务：在同一接口上按顺序返回预设响应，',
877	    '修改场景文件后通过管理入口热更新，更新期间服务不中断。',
878	    '',
879	    'Usage:',
880	    '  node app.ts [--help]',
881	    '  node app.ts serve --config <file> --port <port>',
882	    '',
883	    'Options (serve):',
884	    '  -c, --config <file>   本地 JSON 场景配置文件（必填）',
885	    '  -p, --port <number>   监听端口，0 表示由操作系统分配（必填）',
886	    '                        服务仅监听 127.0.0.1',
887	    '  -h, --help            显示本帮助',
888	    '',
889	    '管理入口（路径前缀 /__contractlab/ 为业务接口保留区之外的保留前缀）：',
890	    '  GET  /__contractlab/health   健康查询，返回当前配置版本',
891	    '  POST /__contractlab/reload   重新读取并热更新同一配置文件',
892	    '',
893	    '配置格式见 README.md。',
894	  ].join('\n');
895	}
896	
897	function cliFail(message: string): never {
898	  process.stderr.write(`${APP_NAME}: ${message}\n`);
899	  process.stderr.write(`运行 'node app.ts --help' 查看用法。\n`);
900	  process.exit(2);
901	}
902	
903	interface ServeOptions {
904	  config: string;
905	  port: number;
906	}
907	
908	function parseServeArgv(argv: readonly string[]): ServeOptions {
909	  let config: string | undefined;
910	  let port: number | undefined;
911	
912	  const readValue = (flag: string, inline: string | undefined, index: number): [string, number] => {
913	    if (inline !== undefined) {
914	      return [inline, index];
915	    }
916	    const value = argv[index + 1];
917	    if (value === undefined) {
918	      cliFail(`serve: 参数 ${flag} 缺少取值`);
919	    }
920	    return [value as string, index + 1];
921	  };
922	
923	  for (let i = 0; i < argv.length; i += 1) {
924	    const token = argv[i];
925	    if (token === '--help' || token === '-h') {
926	      process.stdout.write(`${helpText()}\n`);
927	      process.exit(0);
928	    }
929	
930	    let flag = token;
931	    let inline: string | undefined;
932	    const eq = token.indexOf('=');
933	    if (eq >= 0) {
934	      flag = token.slice(0, eq);
935	      inline = token.slice(eq + 1);
936	    }
937	
938	    if (flag === '--config' || flag === '-c') {
939	      [config, i] = readValue(flag, inline, i);
940	    } else if (flag === '--port' || flag === '-p') {
941	      let value: string;
942	      [value, i] = readValue(flag, inline, i);
943	      if (!/^\d+$/.test(value)) {
944	        cliFail(`serve: 端口必须是整数，收到 "${value}"`);
945	      }
946	      port = Number(value);
947	      if (port < 0 || port > 65535) {
948	        cliFail(`serve: 端口必须在 0 至 65535 之间，收到 ${port}`);
949	      }
950	    } else {
951	      cliFail(`serve: 不支持的命令行参数: ${token}`);
952	    }
953	  }
954	
955	  if (config === undefined) {
956	    cliFail('serve: 缺少必填参数 --config <file>');
957	  }
958	  if (port === undefined) {
959	    cliFail('serve: 缺少必填参数 --port <port>');
960	  }
961	  return { config, port };
962	}
963	
964	function main(): void {
965	  const argv = process.argv.slice(2);
966	
967	  // 保留行为：无参数、--help、-h 显示应用名与帮助
968	  if (
969	    argv.length === 0 ||
970	    (argv.length === 1 && (argv[0] === '--help' || argv[0] === '-h'))
971	  ) {
972	    process.stdout.write(`${helpText()}\n`);
973	    return;
974	  }
975	
976	  if (argv[0] === 'serve') {
977	    const options = parseServeArgv(argv.slice(1));
978	    startServer(options.config, options.port).catch((e: unknown) => {
979	      process.stderr.write(`${APP_NAME}: 启动失败：${describeError(e)}\n`);
980	      process.exit(1);
981	    });
982	    return;
983	  }
984	
985	  // 不支持的命令行参数：报错并以状态码 2 退出
986	  process.stderr.write(`${APP_NAME}: 不支持的命令行参数: ${argv.join(' ')}\n`);
987	  process.stderr.write(`运行 'node app.ts --help' 查看用法。\n`);
988	  process.exit(2);
989	}
990	
991	main();
992

