import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';

const APP = '/Users/Shared/products-20261005/contractlab/b/task003/app.ts';
const fs = await import('node:fs');

function config(rule){
  const ep = rule==null
    ? {method:'POST',path:'/x',responses:[{status:200,headers:{},body:'ok',delay:0}]}
    : {method:'POST',path:'/x',requestBody:rule,responses:[{status:200,headers:{},body:'ok',delay:0}]};
  return JSON.stringify({endpoints:[ep]});
}
let seq=0;
function writeCfg(rule){const f=`/tmp/cltest/cfg_${seq++}.json`;fs.writeFileSync(f,config(rule));return f;}

async function startServer(rule){
  const f=writeCfg(rule);
  const p=spawn('node',[APP,'serve','-c',f,'-p','0'],{stdio:['ignore','pipe','pipe']});
  let buf='';
  const port=await new Promise((res,rej)=>{
    p.stdout.on('data',d=>{buf+=d;const m=buf.match(/127\.0\.0\.1:(\d+)/);if(m)res(+m[1]);});
    p.stderr.on('data',d=>{ /* ignore */ });
    setTimeout(()=>rej(new Error('timeout '+buf)),5000);
  });
  return {p,port,stop:()=>p.kill('SIGTERM')};
}
async function post(port,ce){
  const headers={};
  for(const[k,v]of Object.entries(ce.headers||{}))headers[k]=v;
  if(ce.body!==''){headers['Content-Length']=Buffer.byteLength(ce.body);}
  const r=await fetch(`http://127.0.0.1:${port}${ce.path}`,{method:ce.method,headers,body:ce.body||undefined});
  return r.status;
}
function compatReport(of,nf){
  // 同步执行 node
  const {execFileSync}=await import('node:child_process');
}
import { execFileSync } from 'node:child_process';

const CASES=[
 ['number->integer',{type:'number'},{type:'integer'},false],
 ['string->bool',{type:'string'},{type:'boolean'},false],
 ['new required',{type:'object',fields:{a:{type:'string'}}},{type:'object',fields:{a:{type:'string'},b:{type:'number',required:true}}},false],
 ['delete field closed',{type:'object',fields:{a:{type:'string'}},additionalProperties:true},{type:'object'},false],
 ['array items',{type:'array',items:{type:'number'}},{type:'array',items:{type:'integer'}},false],
 ['nested obj req',{type:'object',fields:{o:{type:'object',fields:{x:{type:'string'}}}}},{type:'object',fields:{o:{type:'object',fields:{x:{type:'string',required:true}}}}},false],
 ['no rule -> rule',null,{type:'object'},false],
 ['proto field',{type:'object',fields:{'__proto__':{type:'string'}}},{type:'object',fields:{'__proto__':{type:'integer'}}},false],
 ['empty name',{type:'object',fields:{'':{type:'string'}}},{type:'object',fields:{'':{type:'integer'}}},false],
 ['int->number OK',{type:'integer'},{type:'number'},true],
 ['add optional closed OK',{type:'object',fields:{a:{type:'string'}}},{type:'object',fields:{a:{type:'string'},b:{type:'string'}}},true],
 ['delete field open OK',{type:'object',fields:{a:{type:'string'}},additionalProperties:true},{type:'object',additionalProperties:true},true],
];

let failures=0;
for(const [name,oRule,nRule,expectCompat] of CASES){
  const of=writeCfg(oRule), nf=writeCfg(nRule);
  let stdout,code=0;
  try{stdout=execFileSync('node',[APP,'compat','-o',of,'-n',nf'],{encoding:'utf8'});}
  catch(e){stdout=e.stdout;code=e.status;}
  const report=JSON.parse(stdout);
  const gotCompat=report.compatible;
  if(gotCompat!==expectCompat){console.log(`FAIL ${name}: compat ${gotCompat} expected ${expectCompat} code=${code}`);failures++;continue;}
  if(expectCompat){console.log(`ok   ${name} (compatible, exit 0)`);continue;}
  // verify counterexample against live servers
  const ce=report.endpoints[0].counterexample;
  const oldSrv=await startServer(oRule);
  const newSrv=await startServer(nRule);
  await sleep(50);
  const oldStatus=await post(oldSrv.port,ce);
  const newStatus=await post(newSrv.port,ce);
  oldSrv.stop();newSrv.stop();
  await sleep(30);
  if(oldStatus===200 && newStatus===400){
    console.log(`ok   ${name}: old=${oldStatus} new=${newStatus} body=${ce.body}`);
  }else{
    console.log(`FAIL ${name}: old=${oldStatus} (want200) new=${newStatus} (want400) body=${ce.body}`);
    failures++;
  }
}
console.log(failures===0?'\nALL PASS':'\n'+failures+' FAILURES');
process.exit(failures?1:0);
